class TwoStackQueue:
    def __init__(self):
        self.main = []
        self.spare = []

    def push(self, x: int) -> None:
        self.main.append(x)

    def _front(self, remove):
        while self.main:
            self.spare.append(self.main.pop())
        value = self.spare.pop() if remove else self.spare[-1]
        while self.spare:
            self.main.append(self.spare.pop())
        return value

    def pop(self) -> int:
        return self._front(True)

    def peek(self) -> int:
        return self._front(False)

    def empty(self) -> bool:
        return not self.main

