class TwoStackQueue {
    private final ArrayDeque<Integer> main = new ArrayDeque<>(), spare = new ArrayDeque<>();

    public TwoStackQueue() {
    }

    public void push(int x) {
        main.push(x);
    }

    private int front(boolean remove) {
        while (!main.isEmpty()) spare.push(main.pop());
        int value = remove ? spare.pop() : spare.peek();
        while (!spare.isEmpty()) main.push(spare.pop());
        return value;
    }

    public int pop() {
        return front(true);
    }

    public int peek() {
        return front(false);
    }

    public boolean empty() {
        return main.isEmpty();
    }
}

