        while (!main.empty()) { spare.push(main.top()); main.pop(); }
        int value = spare.top();
        if (remove) spare.pop();
        while (!spare.empty()) { main.push(spare.top()); spare.pop(); }
        return value;
    }

public:
    TwoStackQueue() {
    }

    void push(int x) {
        main.push(x);
    }

    int pop() {
        return front(true);
    }

    int peek() {
        return front(false);
    }

    bool empty() {
        return main.empty();
    }
};

