class TwoStackQueue {
    stack<int> in, out;

    void turn() {
        if (out.empty())
            while (!in.empty()) { out.push(in.top()); in.pop(); }
    }

public:
    TwoStackQueue() {
    }

    void push(int x) {
        in.push(x);
    }

    int pop() {
        turn();
        int value = out.top();
        out.pop();
        return value;
    }

    int peek() {
        turn();
        return out.top();
    }

    bool empty() {
        return in.empty() && out.empty();
